import { useState } from 'react'
import type { CalendarRange } from 'moru-ui'
import { DateRangePicker } from 'moru-ui'

export function Schedule() {
  const [range, setRange] = useState<CalendarRange>({ start: null, end: null })
  return (
    <DateRangePicker label="Project dates" name="schedule" value={range} onValueChange={setRange} />
  )
}
